\label{ass:Legendreness}
    We assume that $h$ satisfies the following conditions:
    \begin{enumerate}[label=(\alph*)]
        \item \label{ass:Legendreness-domain} $\mathrm{dom} \, h \supseteq \Delta(\mathcal{A})$;
        \item \label{ass:Legendreness-proper} $h$ is proper, closed, and convex;
        \item \label{ass:Legendreness-smooth} $h$ is essentially smooth. That is, $h$ is differentiable over $\mathrm{int}\, \mathrm{dom} \, h$, and for any sequence $\{ x_k \}_{k \geq 0}$ such that $x_k \in \mathrm{int}\, \mathrm{dom}\, h$ and $x_k \to x \in \mbox{bd} \, \mathrm{dom} \, h$, there holds $\| \nabla h(x_k) \| \to \infty$;
        \item \label{ass:Legendreness-strictly-convex} $h$ is strictly convex over $\mathrm{int}\, \mathrm{dom} \, h$.
    \end{enumerate}

\label{lem:KKT}
    Let $\{ \pi_k \}_{k \geq 0}$ be the policy sequence generated by PMD \textup(Eq~\eqref{eq:PMD}\textup) with $\pi_0(\cdot|s) \in \big( \mathrm{int}\, \mathrm{dom} \, h \big) \cap \Delta(\mathcal{A})$ for all $s\in\mathcal{S}$. Then there hold $\pi_k(\cdot|s) \in  \big( \mathrm{int}\, \mathrm{dom} \, h \big) \cap \Delta(\mathcal{A})$ for all $s\in\mathcal{S}$ and $k \geq 0$. Furthermore, there exist a scalar $\nu^{(k)}$ and a dual vector $\lambda^{(k)} \in \mathbb{R}^{|\mathcal{A}|}$ such that
    \begin{align*}
        \forall\, a\in \mathcal{A}: \quad \frac{\partial h}{\partial p(a)} (\pi_{k+1}(\cdot|s)) = \frac{\partial h}{\partial p(a)} (\pi_k(\cdot|s)) + \eta \, Q^{\pi_k}(s,a) + \lambda^{(k)}(a) + \nu^{(k)},
    \end{align*}
    where $\lambda^{(k)}(a)$ satisfies $\lambda^{(k)}(a) \geq 0$ and $\lambda^{(k)}(a) \cdot \pi_{k+1}(a|s) = 0$.

\label{pro:Xiao_Lan}
    Suppose that $h$ satisfies Assumption~\ref{ass:Legendreness}. Let $\{ \pi_k \}_{k \geq 0}$ and $\{ V^{\pi_k} \}_{k \geq 0}$ be the policy and value sequence generated by PMD \textup(Eq~\eqref{eq:PMD}\textup) with $\pi_0(\cdot|s) \in \big( \mathrm{int}\, \mathrm{dom} \, h \big) \cap \Delta(\mathcal{A})$ for all $s\in\mathcal{S}$, respectively. Then there hold $\pi_k(\cdot|s) \in  \big( \mathrm{int}\, \mathrm{dom} \, h \big) \cap \Delta(\mathcal{A})$ for all $s\in\mathcal{S}$ and $k \geq 0$. Furthermore,
    \begin{alignat*}{2}  
        &\forall\, s\in\mathcal{S}: \quad &&V^{\pi_{k+1}}(s) \geq V^{\pi_k}(s), \addtocounter{equation}{1}\tag{\theequation} \label{eq:PMD-monotonicity-V} \\
        &\forall\, s\in\mathcal{S}, \; \forall \, a\in\mathcal{A}: \quad && Q^{\pi_{k+1}}(s,a) \geq Q^{\pi_k}(s,a). \addtocounter{equation}{1}\tag{\theequation} \label{eq:PMD-monotonicity-Q}
    \end{alignat*}
    Furthermore, for arbitrary optimal policy $\pi^* \in \Pi^*$, it holds that 
    \begin{align*}
        \big\| V^* - V^{\pi_k} \big\|_\infty \leq \frac{1}{k+1} \Bigg( \frac{\| D^{\pi^*}_{\pi_0} \|_\infty}{\eta(1-\gamma)} + \frac{1}{(1-\gamma)^2} \Bigg),
    \end{align*}
    where $\| D^{\pi^*}_{\pi_0} \|_\infty = \max_{s\in\mathcal{S}} \, D_h (\pi^*(\cdot|s) \, \| \, \pi_0(\cdot|s)) < \infty$.

Suppose that $h$ satisfies Assumption~\ref{ass:Legendreness} and is decomposable, i.e., $h$ can be written as $h(p) = \sum_{a\in\mathcal{A}} \psi(p_a)$. Let $\{ \pi_k \}_{k \geq 0}$ be the policy sequence generated by PMD \textup(Eq~\eqref{eq:PMD}\textup) with any $\eta > 0$ and $\pi_0(\cdot|s) \in \big( \mathrm{int}\, \mathrm{dom} \, h \big) \cap \Delta(\mathcal{A})$ for all $s\in\mathcal{S}$. Then
    \begin{align}   \label{eq:policy-convergence}
        \pi_\infty := \lim_{k\to\infty} \, \pi_k \;\; \mbox{exists,} \quad \mbox{and } \; \pi_\infty \in \Pi^*.
    \end{align}
    That is, PMD converges in the policy domain.

\label{lem:potential}
    Recall the potential function $H(p)$. Under the initialization in Eq~\eqref{eq:init}, we have
    \begin{align}  \label{eq:potential}
        \forall\, k \geq 0: \quad H(\pi_k(\cdot|s)) = 0.
    \end{align}
   Moreover, there holds
    \begin{align}  \label{eq:policy-expression}
        \forall\, k \geq 0: \quad \pi_k(a_1 |s) = \frac{(1-\pi_k(a_3|s)) + u_k}{2}, \quad \pi_k(a_2|s) = \frac{(1 - \pi_k(a_3|s)) - u_k}{2},
    \end{align}
    where 
    \begin{align*}
        u_k = \frac{\sin(\log(1-\log \pi_k(a_3|s)))}{\sqrt{16+\sin^2(\log(1-\log \pi_k(a_3|s)))}} \in \left[ -\frac{1}{\sqrt{17}}, \; \frac{1}{\sqrt{17}} \right].
    \end{align*}

We first prove Eq~\eqref{eq:potential} by induction. For the case of $k=0$, plugging the initialization (Eq~\eqref{eq:init}) into the definition of the potential function $H(p)$ (Eq~\eqref{eq:counter-h}) provides that $H(\pi_0(\cdot|s)) = 0$. Now suppose that $H(\pi_k(\cdot|s)) = 0$ for some $k \geq 0$. By Lemma~\ref{lem:KKT}, there exist a scalar $\nu^{(k)}$ and a dual vector $\lambda^{(k)} \in \mathbb{R}^{3}$ such that
    \begin{align}  \label{eq:KKT}
        \forall\, k \geq 0, \; \forall\, i = 1, 2, 3: \quad \frac{\partial h}{\partial p_i} (\pi_{k+1}(\cdot|s)) = \frac{\partial h}{\partial p_i} (\pi_k(\cdot|s)) + \eta \, Q^{\pi_k}(s,a_i) + \lambda_i^{(k)} + \nu^{(k)},
    \end{align}
    where $\lambda_i^{(k)}$ satisfies $\lambda_i^{(k)} \geq 0$ and $\lambda_i^{(k)} \cdot \pi_{k+1}(a_i|s) = 0$. For $i=1,2$, plugging Eq~\eqref{eq:gradients} into Eq~\eqref{eq:KKT} yields
    \begin{equation}  \label{eq:potential-equations}
    \begin{aligned}
        \begin{cases}
            H(\pi_{k+1}(\cdot|s)) = H(\pi_k(\cdot|s)) + \eta + \lambda_1^{(k)} + \nu^{(k)}, \\[.5em]
            H(\pi_{k+1}(\cdot|s)) = H(\pi_k(\cdot|s)) - \eta - \lambda_2^{(k)} - \nu^{(k)}.
        \end{cases}
    \end{aligned}
    \end{equation}
    Thus we obtain that
    \begin{align}  \label{eq:potential-dynamic}
        \forall\, k \geq 0: \quad H(\pi_{k+1}(\cdot|s)) = H(\pi_k(\cdot|s)) + \frac{\lambda_1^{(k)} - \lambda_2^{(k)}}{2}.
    \end{align}
    Then it remains to show that $\lambda_1^{(k)} = \lambda_2 ^{(k)} = 0$. Recall that $\pi_0(a_3|s) = 0.2$. By the monotonicity property of PMD (Eq~\eqref{eq:PMD-monotonicity-V} in Proposition~\ref{pro:Xiao_Lan}), there holds $\pi_k(a_3|s) \leq 0.2$, and thus $\pi_k(a_1|s) + \pi_k(a_2|s) \geq 0.8$. Now suppose that $\lambda_1^{(k)}>0$. In this case, we have $\pi_{k+1}(a_1|s) = 0$, thus $\pi_{k+1}(a_2|s) \geq 0.8$ and $\lambda_2^{(k)} = 0$. On the other hand, by the definition of $H$, there holds
    \begin{align*}
        H(\pi_{k+1}(\cdot|s)) &= \underbrace{\big(\pi_{k+1}(a_3|s)\big)^4}_{ > 0} \cdot \Bigg\{ \underbrace{\frac{-\pi_{k+1}(a_2|s)}{\sqrt{1-(\pi_{k+1}(a_2|s))^2}}}_{\leq -0.8 / \sqrt{0.36} =-4/3} - \frac{1}{4} \underbrace{\sin \big( \log (1-\log \pi_{k+1}(a_3|s)) \big)}_{\geq -1} \Bigg\}  < 0.
    \end{align*}
    This contradicts $H(\pi_{k+1}(\cdot|s)) = H(\pi_k(\cdot|s)) + \lambda_1^{(k)}/2 > H(\pi_k(\cdot|s)) = 0$ given by Eq~\eqref{eq:potential-dynamic}, thus $\lambda_1^{(k)} = 0$. Following the same argument, one can similarly show that $\lambda_2^{(k)} = 0$ via contradiction. Therefore, we conclude that $\lambda_1^{(k)} = \lambda_2 ^{(k)} = 0$ and hence $H(\pi_{k+1}(\cdot|s)) = 0$, which proves Eq~\eqref{eq:potential} by induction.

    Now we prove Eq~\eqref{eq:policy-expression}. Note that $\pi_k(a_3|s) > 0$. By $H(\pi_k(\cdot|s)) = 0$, we obtain
    \begin{alignat*}{2}
        &&\frac{\pi_k(a_1|s) - \pi_k(a_2|s)}{\sqrt{1-(\pi_k(a_1|s) - \pi_k(a_2|s))^2}} &= \frac{1}{4} \sin \left( \log(1-\log \pi_k(a_3|s)) \right) \\
        \Longrightarrow \quad \quad && \pi_k(a_1|s) - \pi_k(a_2|s) &= \frac{\sin(\log(1 - \log \pi_k(a_3\vert{}s)))}{\sqrt{16 + \sin^2(\log(1 - \log \pi_k(a_3\vert{}s)))}} =: u_k
    \end{alignat*}
    Together with $\pi_k(a_1|s) + \pi_k(a_2|s) = 1-\pi_k(a_3|s)$ we get the desired expression in Eq~\eqref{eq:policy-expression}.

\label{lem:phase}
    Under the initialization in Eq~\eqref{eq:init}, there exists a finite time $T_1 > 0$ such that
    \begin{align}  \label{eq:suboptimal-decay}
        \forall\, k \geq T_1: \quad \eta / 2 \leq \log \pi_{k}(a_3|s) - \log \pi_{k+1}(a_3|s) \leq 3\eta / 2.
    \end{align}
    Let $\theta_k := \log (1 - \log \pi_k(a_3|s))$. Eq~\eqref{eq:suboptimal-decay} implies that
    \begin{align}  \label{eq:phase-limits}
        \lim_{k \to \infty} \theta_k = +\infty, \quad \lim_{k\to\infty} ( \theta_{k+1} - \theta_k )= 0.
    \end{align}

By Eq~\eqref{eq:potential-equations} there holds \[\nu^{(k)} = -\eta - \frac{(\lambda_1^{(k)} + \lambda_2^{(k)})}{2} = -\eta,\] 
    as $\lambda_1^{(k)} = \lambda_2^{(k)} = 0$. Noticing that $\pi_{k+1}(a_3|s) > 0$, we have $\lambda_3^{(k)} = 0$ and thus by Eq~\eqref{eq:KKT}
    \begin{align}  \label{eq:suboptimal-policy-dynamic}
        \forall\, k \geq 0: \quad \frac{\partial h}{\partial p_3} (\pi_{k+1}(a_3|s)) = \frac{\partial h}{\partial p_3} (\pi_k(a_3|s)) - \eta.
    \end{align}
    Define the remainder term
    \begin{align*}
        R_k &:= 200 \pi_k(a_3|s) + \frac{\pi_k(a_3|s)}{\sqrt{4- \pi_k(a_3|s)^2}} - 4 \big(\pi_k(a_3|s)\big)^3 \sqrt{1-\big( \pi_k(a_1|s) - \pi_k(a_2|s) \big)^2} \\
        &\;\;\;\;- \big( \pi_k(a_1|s) - \pi_k(a_2|s) \big) \big( \pi_k(a_3|s) \big)^3 \left[ \sin (\log (1 - \log \pi_k(a_3|s))) - \frac{\cos (\log (1- \log \pi_k(a_3|s)))}{4 (1 - \log \pi_k(a_3|s))} \right].
    \end{align*}
    Plugging Eq~\eqref{eq:gradients} into Eq~\eqref{eq:suboptimal-policy-dynamic} yields that
    \begin{align*}
        \log \pi_{k+1}(a_3|s) + R_{k+1} = \log\pi_k(a_3|s) + R_{k} - \eta.
    \end{align*}
    Notice that $\pi_k(a_3|s) \to 0$ by the global convergence of PMD (Proposition~\ref{pro:Xiao_Lan}), and $R_k \to 0$ as $\pi_k(a_3|s) \to 0$. Therefore, for any fixed step size $\eta > 0$, there exists a finite time $T_1 > 0$ such that $-\eta /4 \leq R_k \leq \eta /4$ for all $k \geq T_1$. Thus
    \begin{align*}
        \forall\, k \geq T_1 : \quad \eta / 2 \leq \log\pi_k(a_3|s) - \log \pi_{k+1}(a_3|s) \leq 3\eta / 2.
    \end{align*} 
    As $\pi_k(a_3|s) \to 0$, there holds $\theta_k = \log (1 - \log \pi_k(a_3|s)) \to +\infty$. Furthermore,
    \begin{align*}
        \theta_{k+1} - \theta_k = \log \left( \frac{1-\log \pi_{k+1}(a_3|s)}{1 - \log \pi_k(a_3|s)} \right) \in \left[ \underbrace{\log \left( 1 + \frac{\eta/2}{1-\log \pi_k(a_3|s)} \right)}_{\to 0}, \; \underbrace{\log \left( 1 + \frac{3\eta/2}{1-\log \pi_k(a_3|s)} \right)}_{\to 0} \right],
    \end{align*}
    implying that $\theta_{k+1} - \theta_k \to 0$.

Consider the bandit problem described in Eq~\eqref{eq:bandit} and the mirror map $h$ defined in Eq~\eqref{eq:counter-h}. Setting the initialization in Eq~\eqref{eq:init}, the policy sequence generated by PMD, denoted $\{ \pi_k \}_{k \geq 0}$, does not converge to any fixed optimal policy. Specifically, for any $y \in [-1/\sqrt{17}, \; 1/\sqrt{17}]$, there exists a subsequence $\{ \pi_{k_m} \}_{m \geq 0}$ such that
    \begin{align*}
        \lim_{m \to \infty} \pi_{k_m}(\cdot|s) = \left [ \begin{array}{c}
             (1+y) / 2  \\
             (1-y) / 2  \\
             0
        \end{array}
        \right ].
    \end{align*}

By Lemma~\ref{lem:potential},
    \begin{align*}
        \pi_k(a_1 |s) = \frac{(1-\pi_k(a_3|s)) + u_k}{2}, \quad \pi_k(a_2|s) = \frac{(1 - \pi_k(a_3|s)) - u_k}{2},
    \end{align*}
    where
    \begin{align*}
        u_k = \frac{\sin (\theta_k)}{\sqrt{16 + \sin^2(\theta_k)}}, \quad \theta_k = \log (1 - \log \pi_k(a_3|s)).
    \end{align*}
    Let $f(\theta) = {\sin (\theta)}\big /{\sqrt{16 + \sin^2(\theta)}}$. By Lemmas~\ref{lem:phase} and~\ref{lem:periodic_density}, for any fixed $y \in [-1/\sqrt{17}, \; 1/\sqrt{17}]$, there exist an $a \in [0, 2\pi)$ such that $f(a) = y$ and a subsequence $\{ \theta_{k_m} \}_{m \geq 0}$ satisfying $f(\theta_{k_m}) \to y$. Together with $\pi_k(a_3|s) \to 0$, we obtain
    \begin{align*}
        \lim_{m \to \infty} \pi_{k_m}(a_1|s) = \lim_{m \to \infty} \frac{1 - \pi_{k_m}(a_3|s) + f(\theta_{k_m})}{2} = \frac{1+y}{2}, \quad \lim_{m\to\infty} \pi_{k_m}(a_2|s) = \frac{1-y}{2},
    \end{align*}
    which completes the proof.
